class Solution {
public:
    bool canThreePartsEqualSum(vector<int>& arr) {
        int total = 0;
        for (int x : arr) total += x;
        if (total % 3 != 0) return false;
        int target = total / 3;
        int parts = 0;
        int cur = 0;
        for (int x : arr) {
            cur += x;
            if (cur == target) {
                parts++;
                cur = 0;
            }
        }
        return parts >= 3;
    }
};

